INSERT INTO companies (employer_id, name, slug, logo_url, website, size, description, created_at, updated_at) VALUES (2, 'CÔNG TY CỔ PHẦN DỊCH VỤ DI ĐỘNG TRỰC TUYẾN', 'cong-ty-co-phan-dich-vu-di-dong-truc-tuyen', 'https://cdn-new.topcv.vn/unsafe/https://static.topcv.vn/company_logos/cong-ty-co-phan-dich-vu-di-dong-truc-tuyen-vi-momo-967e226f937dcdeb59e8a5477780a2a0-66bde0545e070.jpg', 'https://momo.vn/', '100-499 nhân viên', 'MoMo là siêu ứng dụng hàng đầu và là một trong những Fintech phát triển nhanh nhất tại Việt Nam với nhiều giải thưởng trong nước và quốc tế.

Tính hết tháng 12/2021, MoMo có hơn 30 triệu người dùng, hơn 30.000 đối tác trong nước, 120.000 điểp chấp nhận thanh toán trên toàn quốc liên kết với 30 ngân hàng và thẻ quốc tế. Với hệ sinh thái rộng khắp, người dùng có thể sử dụng Siêu ứng dụng MoMo cho mọi hoạt động hàng ngày, mọi lúc - mọi nơi.

Hơn 1.500 nhân viên với trụ sở chính tại TP HCM, các văn phòng tại Hà Nội, Đà Nẵng, MoMo hướng đến tầm nhìn: Mang đến cơ hội bình đẳng cho tất cả người dân Việt Nam trong việc tiếp cận các sản phẩm, dịch vụ tài chính

Qua đó, MoMo thực hiện sứ mệnh:

- Sử dụng công nghệ di động để cung cấp các giải pháp thanh toán và dịch vụ tài chính nhanh hơn, tốt hơn, an toàn hơn cho mọi người Việt Nam với chi phí thấp.

- Trở thành siêu ứng dụng đáp ứng TẤT CẢ nhu cầu của người dùng.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO companies (employer_id, name, slug, logo_url, website, size, description, created_at, updated_at) VALUES (2, 'CÔNG TY TNHH PHÂN PHỐI SAP BEBE', 'cong-ty-tnhh-phan-phoi-sap-bebe', 'https://cdn-new.topcv.vn/unsafe/https://static.topcv.vn/company_logos/PW0xVFZxG9OTK6aFUE9sZo871vMKCgFy_1762309991____bd5c40ded0b2441d5165fd09e1dc4a23.png', 'https://mapleco.vn/', '10-24 nhân viên', 'SAP Bebe là một start-up trẻ hoạt động trong lĩnh vực mẹ & bé, với sứ mệnh mang đến những sản phẩm an toàn, tinh tế và chuẩn quốc tế cho trẻ nhỏ tại Việt Nam. Chúng tôi là đơn vị độc quyền phân phối thương hiệu Maple&Co – dòng ghế ô tô và xe đẩy cao cấp được thiết kế bởi IDEO (Mỹ) và phát triển cùng Volvo/Adient. Tại SAP Bebe, chúng tôi không chỉ kinh doanh sản phẩm mà còn xây dựng phong cách sống “Safe & Stylish” cho các bậc phụ huynh hiện đại. Với đội ngũ trẻ, sáng tạo và tràn đầy năng lượng, SAP Bebe hướng đến trở thành cầu nối giữa các thương hiệu quốc tế và thế hệ cha mẹ Việt năng động.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO companies (employer_id, name, slug, logo_url, website, size, description, created_at, updated_at) VALUES (2, 'CÔNG TY TNHH BARTELS', 'cong-ty-tnhh-bartels', 'https://cdn-new.topcv.vn/unsafe/https://static.topcv.vn/company_logos/GTPjCg3aiDoPtxb08F0rSmfRsiZjD25M_1748671621____edef3bd3433bc1d475446bbd4903b1c4.png', 'http://bartelsthailand.com/', '100-499 nhân viên', 'Tại Bartels, chúng tôi làm bánh mì chua thủ công, ép nước trái cây tươi theo yêu cầu, pha cà phê ngon và chuẩn bị bánh mì sandwich thủ công với bánh mì chua vừa mới nướng.

Các địa điểm của chúng tôi tại Thái Lan được thiết kế theo phong cách Scandinavia, tạo nên một không gian lý tưởng cho các buổi gặp gỡ bạn bè, họp mặt không chính thức, hoặc đơn giản là làm việc như một văn phòng trong ngày.

Những ổ bánh mì chua của chúng tôi được nướng tươi mỗi ngày, suốt cả ngày, ngay tại cửa hàng. Khi khách hàng mua một chiếc sandwich hoặc một ổ bánh mì, chúng tôi cam kết ổ bánh đó không bao giờ được nướng quá 3 tiếng trước.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO companies (employer_id, name, slug, logo_url, website, size, description, created_at, updated_at) VALUES (2, 'Công ty Cổ phần Đồng Tâm', 'cong-ty-co-phan-dong-tam', 'https://cdn-new.topcv.vn/unsafe/https://static.topcv.vn/company_logos/cong-ty-co-phan-dong-tam-5a124d52ca87c_rs.jpg', '
http://dongtam.com.vn/vi/', '1000+ nhân viên', 'Dongtam Group là một trong những doanh nghiệp hàng đầu Việt Nam về sản xuất và kinh doanh các sản phẩm vật liệu xây dựng, trang trí nội – ngoại thất. Bên cạnh đó, chúng tôi còn mở rộng lĩnh vực đầu tư kinh doanh bất động sản, phát triển khu công nghiệp, khu dân cư, xây dựng nhà, kinh doanh đầu tư cảng biển quốc tế, giáo dục … Với 56 năm hình thành và phát triển, đến nay, Dongtam Group với 16 công ty thành viên và liên kết; Trong đó hệ thống phân phối rộng khắp với 28 chi nhánh (70 showroom và kho hàng) và trên 2.500 cửa hàng cộng tác, nhà phân phối trải dài khắp cả nước. Sản phẩm Đồng Tâm cũng đã xuất khẩu đến 30 quốc gia trên khắp năm châu trên thế giới.

Với sứ mệnh “Đem đến những tiện ích, hiện đại, sang trọng và thẩm mỹ cho cộng đồng, xã hội” và khát vọng – hoài bão “trở thành một trong những công ty hàng đầu trong khu vực châu Á và là đối tác được biết đến bởi thị trường trong nước và nước ngoài”, Dongtam Group là điểm đến hấp dẫn cho những ứng viên trẻ, đầy nhiệt huyết, năng động, đam mê nghề nghiệp, chấp nhận thử thách trong công việc, mong muốn hợp tác lâu dài và phát triển bản thân.
Chúng tôi sẵn sàng chào đón bạn trở thành thành viên của Dongtam Group.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO companies (employer_id, name, slug, logo_url, website, size, description, created_at, updated_at) VALUES (2, 'Hệ Thống Anh Ngữ Quốc tế OCEAN EDU', 'oceaneduvn', 'https://cdn-new.topcv.vn/unsafe/135x/https://static.topcv.vn/company_logos/he-thong-anh-ngu-quoc-te-ocean-edu-63dccf7a2ac89.jpg', 'https://ocean.edu.vn', '1000+ nhân viên', 'Hệ thống Anh ngữ quốc tế Ocean Edu là tổ chức giáo dục Anh ngữ uy tín tại Việt Nam với các chương trình học chuẩn quốc tế đáp ứng nhu cầu học tập cho nhiều lứa tuổi. Trải qua 19 năm hình thành và phát triển, Ocean Edu đã nâng tổng số lên gần 200 chi nhánh đào tạo tại khắp các tỉnh thành trên toàn quốc.

Ocean Edu đã và đang nỗ lực trở thành tập đoàn giáo dục hàng đầu Việt Nam, góp phần thay đổi nền giáo dục tiếng Anh của nước nhà và nâng tầm vị thế của người Việt trên trường quốc tế.

▪︎ Tầm nhìn: Xây dựng tổ hợp giáo dục với hệ thống rộng khắp và xây dựng Ocean Edu City với quy mô lớn. Phấn đấu trở thành tổ hợp giáo dục hàng đầu Việt Nam và mở rộng hoạt động sang khu vực, châu lục.

▪︎ Sứ mệnh: Nâng cao giá trị tri thức cho cộng đồng và xã hội thông qua các khóa học, chương trình đào tạo chuyên nghiệp, đáp ứng nhu cầu ngày càng cao của xã hội.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO companies (employer_id, name, slug, logo_url, website, size, description, created_at, updated_at) VALUES (2, 'CÔNG TY TNHH TỔ CHỨC SỰ KIỆN SÔNG LAM', 'cong-ty-tnhh-to-chuc-su-kien-song-lam', 'https://cdn-new.topcv.vn/unsafe/https://static.topcv.vn/company_logos/skN00zZfm5ADgFn5dV6HmlqxEte7sxF6_1677478708____06d3696eecf1b70383feda099464e3fb.png', 'https://sukiensonglam.com/', '10-24 nhân viên', 'Sự kiện Sông Lam hoạt động trong lĩnh vực cung cấp các thiết bị tổ chức sự kiện ngoài trời tại khu vực TPHCM và các tỉnh thành lân cận. Công ty chuyên sản xuất bán và cho thuê nhà bạt không gian, nhà bạt sự kiện, rạp sự kiện, dù sự kiện, gian hàng hội chợ, gian hàng nhà bạt, nhà lều bạt, cổng hơi, sân khấu, backdrop, bàn ghế sự kiện, ....

Liên hệ Sự kiện Sông Lam
Địa chỉ: Thửa 3097 đường Lê Văn Tiên, khu phố Đông Chiêu, phường Tân Đông Hiệp, thành phố Dĩ An, tỉnh Bình Dương.
SĐT: 0983806682 - 0979231921
Email:  sukiensonglam@gmail.com', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO companies (employer_id, name, slug, logo_url, website, size, description, created_at, updated_at) VALUES (2, 'CÔNG TY CỔ PHẦN XUẤT NHẬP KHẨU VÀ THƯƠNG MẠI BB&K', 'cong-ty-co-phan-xuat-nhap-khau-va-thuong-mai-bbk', 'https://cdn-new.topcv.vn/unsafe/https://static.topcv.vn/company_logos/6825a12ec68081747296558.png', 'https://bbk.vn/', '25-99 nhân viên', 'BB&K được thành lập năm 2019 với mục đích nhập khẩu và phân phối các sản phẩm hữu cơ cao cấp. Chúng tôi tự tin dẫn đầu phát triển dòng sản phẩm siêu thực phẩm hữu cơ tại Việt Nam. Để mang tới những sản phẩm hữu cơ tốt nhất tới tay người Việt, chúng tôi luôn cẩn trọng và kĩ lưỡng trong việc lựa chọn hợp tác với những nhà sản xuất và phân phối lớn và có uy tín cao trên thế giới.

Các sản phẩm hữu cơ của BB&K nhập khẩu độc quyền đã được phân phối hơn 500 siêu thị, cửa hàng bán lẻ và trên 1000 shop online trên toàn quốc.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO companies (employer_id, name, slug, logo_url, website, size, description, created_at, updated_at) VALUES (2, 'CÔNG TY TNHH EASYLEARN DIGITAL', 'cong-ty-tnhh-easylearn-digital', 'https://cdn-new.topcv.vn/unsafe/https://static.topcv.vn/company_logos/69a56123355c21772445987.jpg', '', '25-99 nhân viên', 'CÔNG TY TNHH EASYLEARN DIGITAL là doanh nghiệp hoạt động trong lĩnh vực công nghệ giáo dục, chuyên cung cấp các giải pháp đào tạo trực tuyến và nền tảng học tập số cho cá nhân và doanh nghiệp. Với định hướng lấy công nghệ làm nền tảng phát triển, công ty tập trung xây dựng hệ sinh thái học tập hiện đại, linh hoạt và dễ tiếp cận. EASYLEARN DIGITAL không ngừng đổi mới nội dung, tối ưu trải nghiệm người dùng và ứng dụng các công cụ số nhằm nâng cao hiệu quả đào tạo, góp phần thúc đẩy quá trình chuyển đổi số trong lĩnh vực giáo dục và phát triển nguồn nhân lực tại Việt Nam.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO companies (employer_id, name, slug, logo_url, website, size, description, created_at, updated_at) VALUES (2, 'CÔNG TY TNHH ĐẦU TƯ & PHÁT TRIỂN ĐỊA ỐC MINH TÂM', 'minhtamland', 'https://cdn-new.topcv.vn/unsafe/135x/https://static.topcv.vn/company_logos/A4JggxZJvaRWuxyrTZT72xSkTTow9Efs_1753252682____9d8031a1eaebb019f42b6fa7d2f49360.jpg', 'https://minhtamland.vn/', '25-99', 'LOGO & CÂU CHUYỆN NGƯỜI TRỒNG SEN

Biểu tượng hoa sen trong logo Minh Tân Land chính là hình ảnh gắn liền với văn hoá và triết lý của công ty. Sen mọc từ bùn như vẫn vươn lên thanh khiết, toả hương thơm ngát – cũng giống như cách chúng tôi chọn con đường tử tế - minh bạch - kiên định giá trị cốt lõi trong ngành bất động sản nhiều thách thức.

Từ đó, Minh Tâm Land xây dựng hình tượng “Người Trồng Sen" để định vị văn hoá doanh nghiệp:

- Gieo hồn tâm sáng - mỗi nhân sự đều bắt đầu bằng sự tử tế và minh bạch.

- Nuôi dường bồng sệ chuyên nghiệp - chăm sóc, kiên trì như người trồng sen nâng niu từng gốc sen.

- Lan toả giá trị tốt đẹp – thành quả không chỉ là doanh số, mà còn là sự phát triển bền vững, hạnh phúc và niềm tự hào của tập thể.

Với hình ảnh logo hoa sen, Minh Tâm Land khẳng định: chúng tôi không chỉ bán bất động sản, mà còn gieo trồng những giá trị lâu bền cho khách hàng, nhân sự và xã hội.




TẦM NHÌN

2029 trở thành công ty có trải nghiệm nhân sự xuất sắc trong lĩnh vực BĐS tại Việt Nam. 2030 trở thành công ty top 5 doanh số và thị phần các sản phẩm của Vinhomes.




SỨ MỆNH

Kiến tạo trải nghiệm chuyên nghiệp, thịnh vượng khi giao dịch bất động sản.




TRIẾT LÝ KINH DOANH

Khởi nguồn từ 6 giá trị cốt lõi, Minh Tâm Land hướng đến triết lý kinh doanh là đặt khách hàng làm trung tâm của mọi suy nghĩ và hoạt động.

1 - Lấy khách hàng làm trung tâm của mọi suy nghĩ và hoạt động.

2 - Dịch vụ xuất sắc là con đường để chinh phục khách hàng tốt nhất.

3 - Nhân sự là khách hàng lớn nhất của công ty và nhân tài là tài sản quan trọng nhất.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO companies (employer_id, name, slug, logo_url, website, size, description, created_at, updated_at) VALUES (2, 'Công ty TNHH Du Lịch Authentic Asia', 'cong-ty-tnhh-du-lich-authentic-asia', 'https://cdn-new.topcv.vn/unsafe/https://static.topcv.vn/company_logos/lGJWN6zkZMfn62c3XYH0jPJgSv7oMRPQ_1646024873____835fb504bda48dff2507840c73d54632.png', 'www.travelauthenticasia.com', '25-99 nhân viên', 'Travel Authentic Asia is a professional tour operator specialized in organizing tailor-made, private, and small group tours to Vietnam, Laos, Cambodia, Thailand, and Myanmar. 
