INSERT INTO companies (employer_id, name, slug, logo_url, website, size, description, created_at, updated_at) VALUES (2, 'CÔNG TY TNHH VIỆT NAM IDOL', 'cong-ty-tnhh-viet-nam-idol', 'https://cdn-new.topcv.vn/unsafe/https://static.topcv.vn/company_logos/vn6p1RzNbpVKI05hAdlxa44GU3QuxXbQ_1648742942____c5a864b4f8a674e3ca8b6df78ce903f6.jpg', 'https://vietnamidolchannel.com/', '10-24 nhân viên', 'Toả sáng tài năng cùng Vietnamidol
Chúng tôi trực thuộc hệ thống CN của Tiktok Live Việt Nam. Với sứ mệnh “Nơi tài năng toả sáng” là nơi vững vàng cho idol phát triển tài năng. Vietnamidol không ngừng tìm kiếm, đào tạo, hỗ trợ idol bằng cả nhiệt huyết. Chúng tôi luôn đóng vai trò là cầu nối quan trọng giữa nhà sáng tạo nội dung – idol live với nền tảng Tiktok nói riêng và các đối tác trong lĩnh vực giải trí nói chung.

Tầm nhìn của VietnamIdol:
Vietnamidol mong muốn mang đến sự kết nối đầy giá trị với mỗi idol và mỗi đối tác (các brand, các cơ sở doanh nghiệp, các agc,...), mỗi idol khi hợp tác cùng công ty. Đối với idol: Vietnamidol luôn đồng hành cùng các bạn không chỉ trên nền tảng live mà còn là 1 người bạn giúp idol phát triển hơn với tài năng và đam mê của các bạn. Đối với đối tác: Chúng tôi tin rằng sự phát triển lớn mạnh của các đối tác là đóng góp không nhỏ giúp công ty vững mạnh và vươn xa hơn. Luôn mang đến cho khách hàng những trải nghiệm tốt nhất.

Đội ngũ nhân sự chuyên nghiệp:
Với đội ngũ quản lý Idol chuyên nghiệp, trẻ trung, năng động, nhiệt huyết, luôn hỗ trợ tư vấn nhiệt tình. Chúng tôi luôn lắng nghe, thấu hiểu điều bạn cần và hành động vì sự phát triển của bạn. Tự tin rằng mình sẽ là nơi đưa tài năng của các bạn vươn xa hơn, thu hút được nhiều người theo dõi và yêu mến hơn.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO companies (employer_id, name, slug, logo_url, website, size, description, created_at, updated_at) VALUES (2, 'CÔNG TY TNHH JUPITER VIỆT NAM', 'cong-ty-tnhh-jupiter-viet-nam', 'https://cdn-new.topcv.vn/unsafe/https://static.topcv.vn/company_logos/cong-ty-tnhh-jupiter-viet-nam-dd54eecabcb8411b51a851876706fcc0-651e89164b015.jpg', 'https://www.yfyjupiter.com/', '25-99 nhân viên', 'Công ty thuộc tập đoàn  YFY Đài Loan, Tập đoàn đứng thứ 2 thế giới về lĩnh vực giấy. Công ty chuyên sản xuất tất cả các loại hộp đựng sản phẩm cho các nhãn hàng: Adidas, Dell, HP, Bestbuy,..', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO companies (employer_id, name, slug, logo_url, website, size, description, created_at, updated_at) VALUES (2, 'CÔNG TY TNHH NGUYỄN AN NAM', 'cong-ty-tnhh-nguyen-an-nam', 'https://cdn-new.topcv.vn/unsafe/https://static.topcv.vn/company_logos/aB0UOm3i8EO6dQr9KoJNKXpz1Txv16U5_1739525290____d464b8453f1a26159ec17c11bd85b01a.png', 'https://www.nguyenannamcorp.com/', '10-24 nhân viên', 'At AN NAM CORP, we specialize in BUSINESS GROWTH & MAN POWER DEVELOPMENT (BPO, Training & Development, Strategic & Operational Consultancy, Mass Hiring), delivering transformative solutions to businesses of all sizes. Our goal is to serve both local and international clients with innovation and excellence.

Backed by over 20 years of collective experience from our founders and industry experts, AN NAM CORP is dedicated to driving innovative and reliable BPO solutions that empower businesses to grow and lead in a global marketplace.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO companies (employer_id, name, slug, logo_url, website, size, description, created_at, updated_at) VALUES (2, 'TRUNG TÂM ANH NGỮ FOCUS LEARNING', 'trung-tam-anh-ngu-focus-learning', 'https://cdn-new.topcv.vn/unsafe/https://static.topcv.vn/company_logos/homj5iK01IpQKz7weCFxXT26wbrzuTf2_1757669933____ea250d09821e8f97d72a6c5649620d10.png', '', '25-99 nhân viên', 'Được thành lập từ năm 2017, là Hệ thống ngoại ngữ TƯƠNG TÁC TOÀN DIỆN đầu tiên tại Việt Nam, FOCUS Learning đặt chất lượng giảng dạy và kết quả học tập của học viên lên hàng đầu. Với số lượng 12 học viên cho mỗi lớp học, FOCUS mang đến một môi trường tương tác ngoại ngữ tối ưu nhất. Tại FOCUS Learning, chúng tôi tập trung vào giảng dạy tiếng Anh/tiếng Trung cho trẻ từ 4 – 15 tuổi, luyện thi Ielts mọi cấp độ, đào tạo tiếng Anh/ tiếng Trung Giao tiếp cho người đi làm. Bên cạnh đó, chúng tôi còn có các chương trình bồi dưỡng và luyện thi cho học sinh THCS, THPT với nguồn học liệu uy tín từ hội đồng giáo viên có trình độ chuyên môn cao ', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO companies (employer_id, name, slug, logo_url, website, size, description, created_at, updated_at) VALUES (2, 'CÔNG TY TNHH VIỆT PHÚ ĐẠT', 'cong-ty-tnhh-viet-phu-dat', 'https://cdn-new.topcv.vn/unsafe/https://static.topcv.vn/company_logos/RN59uNZcnI3tQL3hC963Z1EMxhXUgV2l_1700448574____96e634255c7d22588762d4031fe21b90.jpg', 'https://vietphudat.com/', '25-99 nhân viên', 'Công ty TNHH Việt Phú Đạt được thành lập từ năm 2017, Đơn vị sở hữu và quản lý Thương hiệu OVOVITA.

Là một trong những công ty hoạt động uy tín trong lĩnh vực sản xuất kinh doanh Thực Phẩm tại Việt Nam. Công ty Việt Phú Đạt chuyên nhập khẩu nguyên liệu-phụ gia thực phẩm từ các nhà cung cấp nổi tiếng thế giới như: Đức, Pháp, Italia, India,... và phân phối đến các Các công ty sản xuất thực phẩm, Thực Phẩm Thể Thao, hóa mỹ phẩm, Thủy Sản; và các ngành công nghiệp khác. 

Tham gia vào đội ngũ nhân viên, bạn sẽ được tích lũy các kiến thức từ tổng quát tới chuyên sâu, đồng thời, chúng tôi sẽ không ngừng hỗ trợ các bạn thông qua các lớp đào tạo kỹ năng để có cơ hội phát triển và thăng tiến trong công việc.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO companies (employer_id, name, slug, logo_url, website, size, description, created_at, updated_at) VALUES (2, 'Công ty Cổ phần TOPCV Việt Nam', 'topcv', 'https://cdn-new.topcv.vn/unsafe/135x/https://static.topcv.vn/company_logos/WphKX6IinchU9MgvLKMhq1xedm8Qz4w8_1729069676____4ce6db44df6ec10a196cea547700374d.png', 'https://www.topcv.vn/', '100-499', 'Về TOPCV:
TopCV là công ty tiên phong trong lĩnh vực Công nghệ nhân sự tại Việt Nam xoay quanh Hệ sinh thái HR Tech với 4 sản phẩm chủ lực: Nền tảng công nghệ tuyển dụng thông minh TopCV.vn, Nền tảng thiết lập và đánh giá năng lực nhân viên TestCenter.vn, Nền tảng quản lý và gia tăng trải nghiệm nhân viên HappyTime.vn và Giải pháp quản trị tuyển dụng hiệu suất cao SHiring.ai. Hiện TopCV đang sở hữu hệ thống dữ liệu kho dữ liệu hơn 9.5 triệu ứng viên, 200.000+ doanh nghiệp đối tác sử dụng dịch vụ trong đó có nhiều đối tác lớn như FPT, Viettel, Vingroup, VNPT, Techcombank,...kết nối trung bình với 250.000+ ứng viên phù hợp mỗi tháng.
1. Tầm nhìn
Trở thành đơn vị cung cấp giải pháp Công nghệ giúp kết nối và phát triển nguồn nhân lực hàng đầu tại Việt Nam.
2. Sứ mệnh
Kết nối, nâng cao chất lượng nguồn nhân lực cho thị trường lao động giúp các doanh nghiệp Việt Nam phát triển bền vững.
3. Định hướng
Nâng cấp toàn diện Nền tảng tuyển dụng ứng dụng sâu trí thông minh nhân tạo. Đa dạng hóa các sản phẩm công nghệ trong cùng hệ sinh thái Quản trị nhân sự.
4. Giá trị cốt lõi
Intergrity -Chính trực và cam kết
Open Minded - Cởi mở và tích cực
People First - Tập trung vào con người ok
Excellence - Hướng tới sự xuất sắc
Innovation - Liên tục thay đổi để dẫn đầu
Move Fast - Phát triển nhanh', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO companies (employer_id, name, slug, logo_url, website, size, description, created_at, updated_at) VALUES (2, 'Công ty Cổ phần Thế Giới Số (DIGIWORLD)', 'cong-ty-co-phan-the-gioi-so-digiworld', 'https://cdn-new.topcv.vn/unsafe/https://static.topcv.vn/company_logos/fxfYyqrL7o9EbbD42aXNySpJPtohIu15_1745398913____bae212c6e41ad23ff4b62d244094bd41.jpg', 'http://digiworld.com.vn/vi/', '500-1000 nhân viên', 'Công ty Cổ phần Thế Giới Số (Digiworld) – Hành trình hơn 25 năm dẫn đầu dịch vụ mở rộng thị trường tại Việt Nam

Thành lập từ năm 1997, Digiworld đã khẳng định vị thế là đơn vị tiên phong và dẫn đầu trong lĩnh vực Dịch vụ Mở rộng Thị trường (Market Expansion Services) tại Việt Nam, đặc biệt là trong ngành công nghệ thông tin và truyền thông (ICT).

Với hơn 20 năm xây dựng uy tín, Digiworld hiện là đối tác chiến lược và nhà phân phối được ủy quyền của hơn 30 thương hiệu công nghệ hàng đầu thế giới, cùng mạng lưới phân phối rộng khắp với 16.000 điểm bán hàng trên toàn quốc.
Digiworld cũng là đơn vị đầu tiên triển khai mô hình E-distribution tại Việt Nam – một dấu ấn tiên phong trong chuyển đổi số ngành phân phối.
Năm 2015, Digiworld chính thức niêm yết trên sàn HOSE với mã cổ phiếu DGW, mở ra giai đoạn phát triển mới với nhiều bước tiến vượt bậc.
Trong suốt hành trình phát triển, Digiworld đã không ngừng gặt hái các giải thưởng danh giá như:

Top 01 Công ty kinh doanh hiệu quả do Nhịp cầu đầu tư bình chọn.
Top 50 thương hiệu Việt Nam giá trị nhất do Brand Finance (Anh) bình chọn.
Top 50 Công ty niêm yết tốt nhất Việt Nam (Forbes bình chọn)
Top 100 Doanh nghiệp phát triển bền vững tại Việt Nam (CSI100)
Digiworld tiếp tục mở rộng hoạt động sang hai ngành hàng đầy tiềm năng là Chăm sóc sức khỏe (Healthcare), tiêu dùng nhanh (FMCG) và thiết bị gia dụng (Home Appliances)
Digiworld mang đến cho các thương hiệu giải pháp trọn gói và linh hoạt để nhanh chóng thâm nhập và mở rộng thị trường Việt Nam thông qua 6 dịch vụ giá trị gia tăng:
Phân tích thị trường – Marketing – Bán hàng – Hậu cần – Hậu mãi – TMĐT D2C và Quản lý chuỗi cửa hàng.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO companies (employer_id, name, slug, logo_url, website, size, description, created_at, updated_at) VALUES (2, 'CÔNG TY TNHH KMR VIỆT NAM', 'cong-ty-tnhh-kmr-viet-nam', 'https://cdn-new.topcv.vn/unsafe/https://static.topcv.vn/company_logos/cong-ty-tnhh-kmr-viet-nam-60af5ffdd37c2.jpg', 'https://kmr.com.vn/', '10-24 nhân viên', 'Là một trong những tổ chức chứng nhận hàng đầu trong lĩnh vực Đánh giá Chứng nhận và Đào tạo các hệ thống quản lý quốc tế như: Hệ thống Quản lý Chất lượng (ISO9001, IATF 16949); hệ thống quản lý Môi trường (ISO 14001); hệ thống Quản lý An toàn sức khỏe nghề nghiệp (ISO 45001), hê thống quản lý An toàn thực phẩm (ISO 22000, HACCP, FSSC 22000) & HTQL An toàn thông tin (ISO 27001) ...

KMR luôn mở ra cơ hội nghề nghiệp cho các ứng viên có năng lực chuyên môn và có mong muốn phát triển nghề nghiệp đồng hành với KMR. Hãy gửi CV cho chúng tôi nếu bạn phù hợp với những vị trí đang tuyển dụng.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO companies (employer_id, name, slug, logo_url, website, size, description, created_at, updated_at) VALUES (2, 'Cty TNHH TTBYT Hoàng Ánh Dương', 'cty-tnhh-ttbyt-hoang-anh-duong', 'https://cdn-new.topcv.vn/unsafe/https://static.topcv.vn/company_logos/cty-tnhh-ttbyt-hoang-anh-duong-603c63eadc561.jpg', 'http://www.hadmedical.vn/', '25-99 nhân viên', 'Công Ty TNHH TTB Y Tế Hoàng Ánh Dương, được thành lập vào ngày 07/04/2004, chuyên nhập khẩu, kinh doanh và phân phối chính thức từ những sản phẩm Y tế tiêu hao, y cụ cho phòng phẫu thuật và các phòng chăm sóc bệnh nhân nặng, dung dịch hóa chất sát khuẩn, đến găng tay y tế, dao phẫu thuật, v.v… Sản phẩm của Công Ty được tiêu thụ trong hầu hết các Bệnh viện, các phòng chăm sóc đặc biệt, các trung tâm phẫu thuật, các phòng thăm khám của Y sĩ, các nơi mua bán vật dụng y tế gia đình và các điểm bán lẻ khắp toàn quốc.

Với đội ngũ có trình độ kỹ thuật cao gồm Dược sĩ, Kỷ sư, và những nhân viên tốt nghiệp Đại học, Công ty chúng tôi luôn hết mình đảm bảo sẽ đáp ứng đầy đủ những nhu cầu của từng khách hàng.

Bên cạnh việc phát triển mạnh các kênh phân phối, Công ty Hoàng Ánh Dương còn là đại diện thương mại độc quyền những sản phẩm vật tư y tế của các nhà sản xuất nổi tiếng của Nhật, Malaysia, Mỹ như: Feather, Hudson RCI, WRP Asia. Không chỉ có thế, Công ty Hoàng Ánh Dương hiện đang là nhà phân phối chính thức các sản phẩm chỉ khâu phẫu thuật, miếng cầm máu, lưới điều trị thoát vị & dung dịch hóa chất sát khuẩn của Johnson & Johnson tại Việt Nam. Các sản phẩm cao cấp trên được công nhận rộng rãi trên thị trường y tế, điển hình là tại các Bệnh viện lớn như: Bệnh viện Ung Bướu, Bệnh viện Chợ Rẫy, Bệnh viện Từ Dũ, Bệnh viện đại Học Y Dược, Bệnh viện đa khoa Trung Ương Huế, Bệnh viện Hữu Nghị Việt Nam CuBa Đồng Hới, Bệnh viện Đa khoa tỉnh Bình Thuận, Bệnh viện tỉnh Bình Dương, Bệnh viện đa khoa tỉnh Đồng Nai, Bệnh viện Đa Khoa Trung Tâm An Giang, Bệnh viện Đa khoa Trung Ương Cần Thơ, v.v...

Nhằm cải tiến phong trào marketing & giới thiệu sản phẩm trên thị trường được phổ biến tốt hơn, Công ty chúng tôi đang xây dựng đội ngũ PR hoạt động rộng rãi tại các tỉnh thành trên toàn quốc.

Với phương châm “Cho cuộc sống tốt hơn, mang sản phẩm chăm sóc sức khỏe tốt nhất đến người tiêu dùng”. Công ty Hoàng Ánh Dương không ngừng nổ lực phấn đấu trở thành đối tác đáng tin cậy nhất và có được niềm tin tất cả khách hàng.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO companies (employer_id, name, slug, logo_url, website, size, description, created_at, updated_at) VALUES (2, 'CÔNG TY TNHH KỸ THUẬT ĐIỆN LOTECH', 'cong-ty-tnhh-ky-thuat-dien-lotech', 'https://cdn-new.topcv.vn/unsafe/https://static.topcv.vn/company_logos/TAbUHgaoqEGnH5vlZl4XOnkvJOIt0hyr_1771923420____c2242929754ba00869d94153f9dc2d61.png', 'https://lotech.com.vn/', '10-24 nhân viên', 'Công ty TNHH Kỹ thuật Điện Lotech là đơn vị hàng đầu Việt Nam trong cung cấp và tư vấn giải pháp tủ trung thế, trạm kiosk và vật tư trung – cao thế.
Lotech phục vụ các nhà thầu, chủ đầu tư khu công nghiệp, nhà máy, cảng biển, sân bay và các dự án hạ tầng kỹ thuật trọng điểm.

Lotech sở hữu đội ngũ kỹ sư điện trình độ cao, am hiểu sâu về thiết kế, tư vấn, thi công lắp đặt tủ trung thế, trạm biến áp đến 110kV và xử lý sự cố hệ thống điện trung – cao thế. Chúng tôi cam kết cung cấp giải pháp kỹ thuật tối ưu, an toàn và hiệu quả vận hành dài hạn cho từng dự án.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO companies (employer_id, name, slug, logo_url, website, size, description, created_at, updated_at) VALUES (2, 'Công ty cổ phần phần mềm ITSOL Holdings', 'cong-ty-co-phan-phan-mem-itsol-holdings', 'https://cdn-new.topcv.vn/unsafe/https://static.topcv.vn/company_logos/cong-ty-co-phan-phan-mem-itsol-holding-0043c8cc313cf697d6d57b736ba4f2ec-6684c82fb4a4f.jpg', 'http://itsol.vn/', '100-499 nhân viên', 'Tầm nhìn:

Chuyên sâu và chuyên nghiệp về cung cấp giải pháp và cung ứng nguồn lực trong lĩnh vực CNTT, ITSol mong muốn trở thành đối tác tin cậy của khách hàng và cộng đồng nhân lực CNTT.

Giải thưởng:

Giải Sao khuê (Dịch vụ Phái cử, Tuyển dụng – 2015)

Top 40 công ty ICT – Top 17 công ty dịch vụ phần mềm (2015)

Top 20 doanh nghiệp CNTT hàng đầu Việt Nam về BPO, ITO & KPO (2016)

Lĩnh vực chuyên sâu:

Phần mềm/Giải pháp cho Doanh nghiệp, Ngân hàng, Bảo hiểm, Di động và IoT

Chi nhánh:

Việt Nam: Hà Nội', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO companies (employer_id, name, slug, logo_url, website, size, description, created_at, updated_at) VALUES (2, 'TỔNG CÔNG TY DỊCH VỤ SỐ VIETTEL - CHI NHÁNH TẬP ĐOÀN CÔNG NGHIỆP - VIỄN THÔNG QUÂN ĐỘI', 'tong-cong-ty-dich-vu-so-viettel-chi-nhanh-tap-doan-cong-nghiep-vien-thong-quan-doi', 'https://cdn-new.topcv.vn/unsafe/https://static.topcv.vn/company_logos/6NC4c6xmsA1knjOJEVHI55QV2XdCa0nD_1767601631____6343b2e9d83eb84cc6c3769621aff363.png', 'https://viettelmoney.vn/viettel-digital/', '500-1000 nhân viên', 'Tổng Công ty Dịch vụ số Viettel - Viettel Digital Service (VDS) là Tổng công ty thành viên thứ 8 của Tập đoàn Công nghiệp Viễn thông Quân đội Viettel, mang sứ mệnh tiên phong kiến tạo tài chính toàn diện. Sản phẩm nổi bật nhất của VDS là Hệ sinh thái tài chính số Viettel Money, nằm trong nhóm trung gian thanh toán dẫn đầu thị trường Việt Nam về quy mô. Bên cạnh đó, VDS là đơn vị cung cấp các giải pháp nền tảng thanh toán tại 07 thị trường nước ngoài, với quy mô khách hàng đạt ~ 50 triệu.
Hiện nay, Viettel Digital đang mở rộng hoạt động trong lĩnh vực Fintech, đặt mục tiêu trở thành hạt nhân công nghệ dẫn dắt chuyển đổi số cho ngành tài chính với tầm nhìn trở thành hệ sinh thái công nghệ tài chính toàn cầu vào năm 2030.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO companies (employer_id, name, slug, logo_url, website, size, description, created_at, updated_at) VALUES (2, 'CÔNG TY CỔ PHẦN GOOD REVIEW SERVICE', 'cong-ty-co-phan-good-review-service', 'https://cdn-new.topcv.vn/unsafe/https://static.topcv.vn/company_logos/68185d809776c1746427264.png', 'https://goodreviewservice.com/', '25-99 nhân viên', 'Good Review Service is a full-service performance marketing agency, nestled in the heart of Champaign, Illinois. Understands the criticality of reviews in today’s market. Leveraging their expertise in digital marketing,we provide businesses to harness the power of positive feedback. Our strategic methods not only encourage customer engagement but also cultivate a flourishing environment for brand advocacy.

Good Review Service:

Cung cấp giải pháp quảng cáo Facebook, Instagram, Tiktok, Youtube, Google hiệu quả nhất và tốt nhất 50 tiểu bang.
Hỗ trợ quản lí, chăm sóc và phát triển chuyên nghiệp cho các trang social của bạn.
SEO Top #1 Google Seach.
Combo Marketing Full Service...', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO companies (employer_id, name, slug, logo_url, website, size, description, created_at, updated_at) VALUES (2, 'CÔNG TY TNHH TECHCARE', 'cong-ty-tnhh-techcare', 'https://cdn-new.topcv.vn/unsafe/https://static.topcv.vn/company_logos/xoh72GtpVwJ2I4zYuMxR1TvO9bAN5o6h_1776583144____ad14557331e2800cebf0fd8548883bd0.png', '', '10-24 nhân viên', 'TechCare là startup chuyên cung cấp giải pháp outsource nhân lực công nghệ thông tin cho các doanh nghiệp Châu Âu, tập trung vào gia công và phát triển phần mềm theo yêu cầu. Với đội ngũ kỹ sư chất lượng cao, TechCare giúp khách hàng tối ưu nguồn lực, rút ngắn thời gian triển khai và nâng cao hiệu suất dự án. Không chỉ là nhà cung cấp dịch vụ, TechCare còn là đối tác chiến lược, luôn đồng hành cùng khách hàng trong việc duy trì, cải tiến và mở rộng sản phẩm. Công ty hướng đến việc xây dựng mối quan hệ lâu dài, mang lại giá trị bền vững và góp phần thúc đẩy sự phát triển liên tục của đối tác trong môi trường công nghệ đầy cạnh tranh.

', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
