INSERT INTO companies (employer_id, name, slug, logo_url, website, size, description, created_at, updated_at) VALUES (2, 'CÔNG TY TNHH LEADO VIỆT NAM', 'cong-ty-tnhh-leado-viet-nam', 'https://cdn-new.topcv.vn/unsafe/https://static.topcv.vn/company_logos/6899c9a8972631754909096.jpg', 'https://gaaborvn.com/', '25-99 nhân viên', 'Leado là một công ty thương mại điện tử hoạt động ở cả hai lĩnh vực B2B và B2C. Chúng tôi là Thành viên của Leado tại Việt Nam. Chúng tôi cung cấp các giải pháp toàn diện về dịch vụ B2C cho các Nhãn hàng và Người bán. Dịch vụ của chúng tôi bao gồm Vận hành Gian hàng, Tiếp thị Kỹ thuật số, Creative Design biên tập hình ảnh và video, Hệ thống Chăm sóc Khách hàng và Kho vận, Biên tập hình ảnh và video, Hệ thống Chăm sóc Khách hàng và Kho vận. Chúng tôi hiện có trụ sở tại một số quốc gia có tốc độ phát triển thương mại điện tử nhanh nhất là Indonesia, Trung Quốc, Việt Nam, Thái Lan, Philippin, Malaixia và Singapo...

', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO companies (employer_id, name, slug, logo_url, website, size, description, created_at, updated_at) VALUES (2, 'CÔNG TY CỔ PHẦN QUẢN LÝ BẤT ĐỘNG SẢN DKRA', 'cong-ty-co-phan-quan-ly-bat-dong-san-dkra', 'https://cdn-new.topcv.vn/unsafe/https://static.topcv.vn/company_logos/6mMT7CBKZS5L5JN9VMGerdOoTkEqK1tH_1701320551____a0f44738211393d7d11bb4682bbfcca4.jpg', 'https://dkraliving.vn/', '100-499 nhân viên', 'Thừa hưởng các giá trị cốt lỗi Tín – Trí – Đức của hệ thống DKRA Việt Nam.

DKRA Living đã tập trung phát triển dịch vụ quản lý, vận hành cho các loại hình Bất động sản, tối ưu hóa hiệu quả các dịch vụ, trở thành đơn vị quản lý và vận hành uy tín, được lựa chọn hàng đầu tại Việt Nam. Hơn 4 năm hình thành và phát triển, đó là kim chỉ nam, là văn hóa chung mà chúng tôi luôn tự hào gìn giữ và phát huy để tạo nên giá trị khác biệt của DKRA Living. Với đội ngũ nhân sự giàu kinh nghiệm, quy trình quản lý vận hành tiên tiến cùng ứng dụng công nghệ hiện đại, DKRA Living mang đến các giải pháp thực tiễn và toàn diện nhất đến với khách hàng. Tính hiệu quả trong công việc và sự hài lòng của khách hàng là phần thưởng quý giá mà chúng tôi luôn khao khát. Với những nền tảng đã xây dựng, chúng tôi hoàn toàn tin tưởng trong tương lai, DKRA Living sẽ ngày càng phát triển mạnh mẽ, hướng tới mục tiêu trở thành thương hiệu lớn và uy tín được tin tưởng lựa chọn đầu tiên trong lĩnh vực tư vấn và quản lý vận hành bất động sản Việt Nam.

DKRA Living chân thành cảm ơn sự hợp tác, tín nhiệm của các cổ đông, khách hàng và đối tác cũng như sự cống hiến của tập thể nhân viên trong thành công của Công ty. Chúng tôi mong muốn sẽ luôn nhận được sự đồng hành và ủng hộ của các cổ đông, khách hàng và đội ngũ nội bộ trên con đường phía trước.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO companies (employer_id, name, slug, logo_url, website, size, description, created_at, updated_at) VALUES (2, 'CÔNG TY TRÁCH NHIỆM HỮU HẠN HUNG WAY', 'cong-ty-trach-nhiem-huu-han-hung-way', 'https://cdn-new.topcv.vn/unsafe/https://static.topcv.vn/company_logos/69e19bc40fa2d1776393156.jpg', '', '500-1000 nhân viên', 'Công ty TNHH HUNG WAY, được thành lập năm 1996, với khoảng 1.800 công nhân viên, tọa lạc tại Khu Chế Xuất Tân Thuận. Là một Công Ty Đài Loan, chuyên may găng tay trượt tuyết, găng tay chống rét quần thể thao và áo Jacket, chuyên sản xuất hàng hiệu, 100% xuất khẩu toàn cầu.

Hàng may mặc của công ty chúng tôi được sản xuất bằng các trang thiết bị hiện đại nhưng cũng đòi hỏi sự tỉ mĩ trong từng sản phẩm.Từ khi thành lập đến nay công ty chúng tôi đã không ngừng cải tiến công nghệ, đầu tư trang thiết bị, môi trường làm việc thoáng mát, các chuyền may đều có gắn máy lạnh, đài thọ 2 tòa nhà ký túc xá, mỗi toàn 80 phòng/ 5 tầng cho công nhân ở miễn phí. Nâng cao chất lượng sản phẩm. Thường xuyên mở các lớp tập huấn để nâng cao trình độ quản lý và tay nghề công nhân.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO companies (employer_id, name, slug, logo_url, website, size, description, created_at, updated_at) VALUES (2, 'HSBC', 'hsbc', 'https://cdn-new.topcv.vn/unsafe/https://static.topcv.vn/company_logos/hsbc-5900283bbf87c_rs.jpg', 'https://www.hsbc.com.vn/', '500-1000 nhân viên', 'Năm 1870 HSBC mở văn phòng đầu tiên tại Sài Gòn (nay là TP. Hồ Chí Minh). Tháng 8 năm 1995, chi nhánh tại thành phố Hồ Chí Minh được cấp phép hoạt động và cung cấp đầy đủ các dịch vụ tài chính ngân hàng. HSBC khai trương chi nhánh thứ hai tại Hà Nội và thành lập Văn phòng Đại diện tại Cần Thơ vào năm 2005.

Ngày 01 tháng 01 năm 2009, HSBC khai trương ngân hàng 100% vốn nước ngoài và trở thành ngân hàng nước ngoài đầu tiên đưa ngân hàng con đi vào hoạt động tại Việt Nam. Ngân hàng mới với tên gọi Ngân hàng TNHH một thành viên HSBC (Việt Nam) thuộc 100% sở hữu của Ngân hàng Hồng Kông và Thượng Hải. Ngân hàng TNHH một thành viên HSBC (Việt Nam) là ngân hàng 100% vốn nước ngoài đầu tiên đồng thời đưa chi nhánh và phòng giao dịch đi vào hoạt động tại Việt Nam. Hiện tại, mạng lưới hoạt động của ngân hàng bao gồm một hội sở, một chi nhánh và năm phòng giao dịch tại Tp. Hồ Chí Minh, một chi nhánh, ba phòng giao dịch và một quỹ tiết kiệm tại Hà Nội, bốn chi nhánh tại Bình Dương, Cần Thơ, Đà Nẵng, Đồng Nai và hai văn phòng đại diện tại Hải Phòng và Vũng Tàu.

Hiện tại, HSBC là một trong những ngân hàng nước ngoài lớn nhất tại Việt Nam xét về vốn đầu tư, mạng lưới, chủng loại sản phẩm, số lượng nhân viên và khách hàng.

Với hơn 140 năm kinh nghiệm hoạt động tại thị trường Việt Nam, HSBC cung cấp đầy đủ các dịch vụ tài chính ngân hàng bao gồm: Dịch vụ Tài chính Cá nhân và Quản lý Tài sản, Dịch vụ Tài chính Doanh Nghiệp, Dịch vụ Tài chính toàn cầu, Dịch vụ Ngoại hối và thị trường vốn, Dịch vụ Thanh toán và Quản lý tiền tệ, Dịch vụ Thanh tóan Quốc tế và Tài trợ thương mại, và Dịch vụ Chứng Khoán. Với lịch sử hoạt động lâu đời cũng như sự am hiểu về thị trường Việt Nam, HSBC khẳng định cam kết mang đến những dịch vụ tốt nhất cho khách hàng.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO companies (employer_id, name, slug, logo_url, website, size, description, created_at, updated_at) VALUES (2, 'Tập Đoàn Tân Hoàng Minh', 'tap-doan-tan-hoang-minh', 'https://cdn-new.topcv.vn/unsafe/https://static.topcv.vn/company_logos/b82234f839889712c9e0706aa61b0205-60e2bdca4ca62.jpg', 'http://tanhoangminh.com.vn/', '500-1000 nhân viên', 'Nổi danh trên thị trường với những dự án bất động sản cao cấp dành riêng cho giới thượng lưu, Tân Hoàng Minh là một trong số ít chủ đầu tư dành trọn tâm huyết để kiến tạo nên những “công trình nghệ thuật” hội tụ đầy đủ 5 yếu tố: vị trí đắc địa, chất lượng công trình tiêu chuẩn quốc tế, độ bền công trình vĩnh viễn, thiết kế ấn tượng và trang thiết bị đẳng cấp. Trong đó, chất lượng và độ bền công trình chính là hai yếu tố luôn được Tập đoàn bất động sản trứ danh này chú trọng thực hiện trong mỗi dự án được triển khai.

', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO companies (employer_id, name, slug, logo_url, website, size, description, created_at, updated_at) VALUES (NULL, 'CÔNG TY TNHH BÁNH NGỌT CJ VIỆT NAM', 'cong-ty-tnhh-banh-ngot-cj-viet-nam', 'https://cdn-new.topcv.vn/unsafe/https://static.topcv.vn/company_logos/9b388926db75377f1f294b8dfa4e2860-5e4b4ed22def9.jpg', 'https://bit.ly/32crng5', '100-499 nhân viên', 'TOUS les JOURS là tiệm bánh cao cấp số 1 tại Việt Nam. Dẫn đầu xu hướng thị trường và nâng cao chất lượng cuộc sống của khách hàng bằng cách cung cấp những sản phẩm tốt nhất

TOUS les JOURS là thương hiệu của chuỗi cửa hàng bánh mì Hàn Quốc CJ Foodville, một công ty con của Tập đoàn CJ.

Bắt đầu với việc ra mắt cửa hàng Tous les Jours đầu tiên vào năm 2007 tại Việt Nam, tiệm bánh nổi tiếng thế giới này đã khẳng định được vị thế là một trong những tiệm bánh cà phê uy tín nhất cả nước, xây dựng hình ảnh thương hiệu được tôn trọng không chỉ trong cộng đồng châu Á mà còn cả cộng đồng phương Tây.

TOUS les JOURS là tiệm bánh cao cấp số 1 tại Việt Nam. Dẫn đầu xu hướng thị trường và nâng cao chất lượng cuộc sống của khách hàng bằng cách cung cấp các sản phẩm và dịch vụ tốt nhất

THÔNG ĐIỆP TỪ CJ FOODVILLE VIỆT NAM

Với nhu cầu mở rộng phát triển và khẳng định thương hiệu trên thị trường được người tiêu dùng ưa chuộng nhất.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO companies (employer_id, name, slug, logo_url, website, size, description, created_at, updated_at) VALUES (NULL, 'CÔNG TY TNHH AGS VIETNAM', 'cong-ty-tnhh-ags-vietnam', 'https://cdn-new.topcv.vn/unsafe/https://static.topcv.vn/company_logos/iVCAsPbQlyFBdG1eNcEui9psm6GH0Dwc_1718618149____56ed3a0dddb093ee52f93350299b731a.png', 'https://agservices.com.vn/', '1000+ nhân viên', 'Following a successful M&A in APAC, that has seen ATALIAN Asia, UK & Ireland merging with OCS group, AGS Vietnam (previously ATALIAN) and now partner country to OCS is now part of a 130,000 people organization one of the largest FM service providers in the world, across 4 continents with a very extensive presence in APAC which alone accounts for 11 out of the 27 countries globally.

 

With over 1000 people in Vietnam AGS offers a wide range of the facility management services, which most of them are self-delivered. 

> Facilities: offices, production sites, public sector, retail, residentials, schools, hospitals and others.

> Sectors: Corporate services, Manufacturing, Retail, Food-processing, Distribution and Logistics, Healthcare, Transport, Pharmaceuticals and others.

ATALIAN Servest provides a large range of service lines:

• Facility Management

• Cleaning

• Pest control

• Technical maintenance

• Duct cleaning

• Public sector

• Catering

• Front of house

• Energy Management

• Landscaping

• Finishing works

• Public sector and Hospitality in the cluster

 

AGS Vietnam is headquartered in Ho Chi Minh City and has 2 branch offices, in Danang and Hanoi which allow us to cover the entire nation of Vietnam.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO companies (employer_id, name, slug, logo_url, website, size, description, created_at, updated_at) VALUES (NULL, 'Công ty Cổ Phần Con Cưng', 'cong-ty-co-phan-con-cung', 'https://cdn-new.topcv.vn/unsafe/https://static.topcv.vn/company_logos/02bzHDVE4BxGcdfxwQ6w.jpg', 'https://careers.concung.com/', '5000+ nhân viên', 'Với sứ mệnh “Hành động vì trẻ em Việt Nam”, Con Cưng Concung.com được sáng lập nhằm mang đến thiên đường mua sắm đầy đủ, tiện nghi với chất lượng và giá thành phù hợp cho mọi gia đình Bỉm sữa Việt Nam. Concung.com luôn thực hiện đúng cam kết đưa sản phẩm trực tiếp từ nhà sản xuất đến tay người tiêu dùng và kiểm soát chất lượng để đáp ứng được nhu cầu ngày càng cao của khách hàng.

Lĩnh vực hoạt động của Concung.com hiện tại bao gồm:

- Phát triển các hệ thống chuỗi bán lẻ cho Mẹ bầu & Em bé: Concung.com, Toycity, CF Con Cung Fashion.

- Nghiên cứu và cho ra đời các sản phẩm an toàn, chất lượng, giá thành hợp lý dành riêng cho trẻ em với thương hiệu Concung.com.

Thành lập từ năm 2011, Concung.com tập trung chủ yếu ở TP. HCM và các tỉnh phía Nam. Năm 2016, Concung.com cán mốc 100 cửa hàng. Năm 2017, Concung.com phủ sóng với 200 cửa hàng, tăng 100% so với năm trước. Cuối năm 2018, Concung.com đã có mặt với hơn 400 cửa hàng trải dài 45 tỉnh/thành Việt Nam và phục vụ trung bình hơn 500.000 khách hàng mỗi tháng.

Với tiêu chí "Ra ngõ đã có Con Cưng", Concung.com kì vọng sẽ đạt mốc 1000 cửa hàng trên toàn quốc, phủ sóng khắp 63 tỉnh thành Việt Nam trong năm 2021 với doanh thu 500 triệu USD/ năm. Xét về quy mô, Concung.com tự hào trở thành chuỗi bán lẻ có tốc độ phát triển đứng đầu thị trường Mẹ và Bé tại Việt Nam hiện nay.

Concung.com chủ động xây dựng một môi trường làm việc trẻ trung, cởi mở và đơn giản. Tại Concung.com, mỗi nhân viên luôn được xem là một cộng sự được ban lãnh đạo tin tưởng cũng như tạo điều kiện tốt nhất để thể hiện và phát huy năng lực bản thân. Ngoài mức thu nhập cạnh tranh theo năng lực không phụ thuộc vào kinh nghiệm, Concung.com thực hiện chính sách xem xét mức thu nhập và lộ trình phát triển sự nghiệp thường xuyên nhằm đảm bảo việc tăng trưởng thu nhập của nhân viên tương ứng với độ phát triển của công ty và khối lượng công việc đảm nhiệm.

Bạn đang tìm kiếm cơ hội việc làm tại Con Cưng? Hãy truy cập các trang thông tin Tuyển dụng chính thức sau:
- Facebook: Con Cung Careers (www.facebook.com/ConCungCareersVN)
- LinkedIn: Con Cung Corporation (Concung.com) (www.linkedin.com/company/concung)
- Career Site: careers.concung.com', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO companies (employer_id, name, slug, logo_url, website, size, description, created_at, updated_at) VALUES (NULL, 'CÔNG TY CỔ PHẦN ASPIRE', 'cong-ty-co-phan-aspire', 'https://cdn-new.topcv.vn/unsafe/https://static.topcv.vn/company_logos/6904410acc00a1761886474.jpg', '', '25-99 nhân viên', 'Established in 2018, Aspire are at the forefront of revolutionizing long-term leasing business in Ho Chi Minh City. Our mission is to provide quality, safe, convenient, and affordable accommodation in Ho Chi Minh City.

We focus on redeveloping properties in strategic locations. Our capital is long-term, and we seek real estate assets which can provide a steady income stream and appreciate in value accordingly.

We adhere to international standards in all aspects of business. We seek individuals to join our company who have a strong desire for growth and share our passion for excellence by upholding the highest levels of integrity and professionalism.

Join us at Aspire to help set an industry standard of living for young professionals in Ho Chi Minh City. Be part of a team striving for success and making a difference.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO companies (employer_id, name, slug, logo_url, website, size, description, created_at, updated_at) VALUES (NULL, 'CÔNG TY TNHH THIẾT KẾ THI CÔNG NỘI THẤT LUXMO', 'cong-ty-tnhh-thiet-ke-thi-cong-noi-that-luxmo', 'https://cdn-new.topcv.vn/unsafe/https://static.topcv.vn/company_logos/G2IYTtTfPS5e0nRrTzCkSi7cL6ACQkVx_1775032610____86282420b27f11dbac622d69ed524ba3.jpg', 'https://luxmo.vn/', '10-24 nhân viên', 'CÔNG TY TNHH THIẾT KẾ THI CÔNG NỘI THẤT LUXMO là đơn vị hoạt động trong lĩnh vực thiết kế và thi công nội thất, chuyên cung cấp các giải pháp không gian sống và làm việc hiện đại, tiện nghi và mang tính thẩm mỹ cao.



Giới thiệu chung



LUXMO tập trung vào việc biến ý tưởng của khách hàng thành những không gian thực tế, hài hòa giữa công năng và phong cách. Công ty thường phục vụ đa dạng nhu cầu như:



Thiết kế nội thất căn hộ, nhà phố, biệt thự

Thi công nội thất văn phòng, showroom, cửa hàng

Cải tạo và nâng cấp không gian sống', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO companies (employer_id, name, slug, logo_url, website, size, description, created_at, updated_at) VALUES (NULL, 'CÔNG TY CỔ PHẦN TƯ VẤN ĐẦU TƯ AN PHÚC SƠN', 'cong-ty-co-phan-tu-van-dau-tu-an-phuc-son', 'https://cdn-new.topcv.vn/unsafe/https://static.topcv.vn/company_logos/As6IcliXF3zeHoo7ReVVjnWXP8vwQPM2_1768471011____95668787a8c80f8e63f64fcad54f41db.jpg', '', '10-24 nhân viên', 'Được thành lập năm 2010, APS Concept là một doanh nghiệp hoạt động chuyên nghiệp trong lĩnh vực thiết kế Kiến trúc – Nội thất – Thi công hoàn thiện và đầu tư xây dựng ở các hạng mục công trình: Căn hộ cao cấp, biệt thự, nhà hàng, khách sạn, văn phòng,..

Sở hữu đội ngũ Kiến trúc sư, Kỹ sư sáng tạo và giàu kinh nghiệm trong lĩnh vực thiết kế và thi công dân dụng. APS Concept cung cấp cho khách hàng dịch vụ thiết kế và thi công chuyên nghiệp, được đảm bảo về chất lượng và tay nghề.

Tập trung vào không gian, đưa ra các giải pháp thiết kế tối ưu, chúng tôi tiếp cận từng dự án một cách chỉn chu, mang đến khách hàng sản phẩm hoàn thiện và độc đáo. Với sự đa dạng trong các dự án, APS Concept chu đáo thiết lập những trải nghiệm thú vị, thoải mái và mang tính cá nhân hóa cho khách hàng', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO companies (employer_id, name, slug, logo_url, website, size, description, created_at, updated_at) VALUES (NULL, 'Công Ty TNHH Phân Phối Tiên Tiến', 'cong-ty-tnhh-phan-phoi-tien-tien', 'https://cdn-new.topcv.vn/unsafe/https://static.topcv.vn/company_logos/cong-ty-tnhh-phan-phoi-tien-tien-58fdc94f5186c.jpg', 'http://www.adcompany.com.vn/portfolio.php', '1000+ nhân viên', 'Công ty Phân Phối Tiên Tiến là 1 trong 500 doanh nghiệp lớn nhất Việt Nam, chuyên phân phối các mặt hàng nhập khẩu: sữa Enfa, Colgate, L''oreal, Wipro, Pepsi Food, Plusssz, Mondelez Kinh Đô, Bánh kẹo Lotte, Nước yến & nước cốt gà Brand''s,…

', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO companies (employer_id, name, slug, logo_url, website, size, description, created_at, updated_at) VALUES (NULL, 'Công ty TNHH Đầu tư Quốc tế Hoàn Mỹ', 'cong-ty-tnhh-dau-tu-quoc-te-hoan-my', 'https://cdn-new.topcv.vn/unsafe/https://static.topcv.vn/company_logos/MhkEL43DBx7iEqTnN7VBvV3ylpyGlgaz_1663227444____ea3e118f165870b113ee93ec26f800e9.jpg', 'https://quoctehoanmy.com/', '25-99 nhân viên', 'Công ty TNHH Đầu tư Quốc tế Hoàn Mỹ (thương hiệu TVBUY) là doanh nghiệp chuyên phân phối các dòng sản phẩm thực phẩm bảo vệ sức khỏe tại Việt Nam.


Trong hành trình xây dựng và phát triển, Hoàn Mỹ luôn cố gắng mang đến cho người tiêu dùng Việt Nam những sản phẩm chất lượng, an toàn nhằm chăm sóc và bảo vệ sức khỏe một cách tốt nhất.


Hoàn Mỹ chuyên phân phối các dòng sản phẩm thực phẩm bảo vệ sức khỏe chất lượng hàng đầu của Mỹ tại thị trường Việt Nam. Các sản phẩm của Hoàn Mỹ đều có nguồn gốc rõ ràng, được FDA Hoa Kỳ và cơ quan quản lý nhà nước Việt Nam cấp phép lưu hành trên toàn quốc, đảm bảo an toàn, tốt nhất cho người sử dụng.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO companies (employer_id, name, slug, logo_url, website, size, description, created_at, updated_at) VALUES (NULL, 'CÔNG TY CỔ PHẦN THE INSPIRERS', 'cong-ty-co-phan-the-inspirers', 'https://cdn-new.topcv.vn/unsafe/https://static.topcv.vn/company_logos/69e88a304538f1776847408.jpg', '', '10-24 nhân viên', 'The Inspirers là đơn vị chuyên tổ chức sự kiện âm nhạc giao hưởng thính phòng. Với ước mơ kết nối và lan tỏa những giá trị tích cực của âm nhạc giao hưởng đến với khán giả Việt Nam, The Inspirers đã tổ chức thành công 17 chương trình âm nhạc khác nhau, hơn 30 đêm diễn, thu hút hơn hàng trăm nghìn khán giả tại Hà Nội và TP. HCM. Trong đó có chuỗi chương trình hòa nhạc ký ức tuổi thơ Concert of Childhood Memory - một trong những chương trình giao hưởng "cháy vé" nhất tại Việt Nam, hay các dự án...

', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);

